insert into institution_regulations
  (regulation_id, institution_id, title, stage, lifecycle_state, current_state_note, next_gate, next_gate_timing, updated_by)
values
  ('reg_ff01bb8086e3_conflict_of_interest', 'inst_catalog_ff01bb8086e3', '東京大学利益相反マネジメント委員会規則', 4, 'effective', 'PDF本文を実際に開き、令和2年3月26日役員会議決・東大規則第121号であることを確認した。上位規範として同日制定の「東京大学利益相反ポリシー」があるが、そのPDF単体URL(旧400103592.pdf)は404で現行リンクを規則集内で特定できなかったため、本規則の条文PDFのみ確認済みとして報告する。', null, null, 'migration:361'),
  ('reg_ff01bb8086e3_side_job', 'inst_catalog_ff01bb8086e3', '東京大学教職員兼業規程', 4, 'effective', 'PDF本文を実際に開き、平成16年4月1日役員会議決・東大規則第26号であることを確認した。役員個別の兼業を扱う「東京大学の役員の兼業に関する内規」、審査体制を定める「東京大学教員営利企業役員等兼業審査委員会規則」もそれぞれ規則集本文ページで存在確認済み(URLはsourceUrl欄以外にcurrentStateNoteで補足)。クロスアポイントメント単独規程は本調査の範囲では発見できなかった。', null, null, 'migration:361'),
  ('reg_ff01bb8086e3_ip_license', 'inst_catalog_ff01bb8086e3', '東京大学発明等取扱規則', 4, 'effective', 'PDF本文を実際に開き、平成16年4月1日東大規則第130号であることを確認した。同じ規則集ページ群に著作物等取扱規則・商標取扱規則・ノウハウ取扱規則も並んで公開されているが、いずれもライセンス許諾自体を主題とする単独の実施許諾規則ではなく発明等の帰属・取扱いが主内容。', null, null, 'migration:361'),
  ('reg_ff01bb8086e3_equity_stock_option', 'inst_catalog_ff01bb8086e3', '東京大学における寄附による株式等取得取扱規則', 4, 'effective', 'PDF本文を実際に開き、平成18年1月30日役員会議決・東大規則第55号であることを確認した。産学協創推進本部ページには「ライセンス及びベンチャー支援に伴う株式等取得取扱規則」「出資を目的とした株式等取得取扱規則」も掲載名として存在するが、それぞれのリンク先(u0740881001.html、h180130057.pdf)は404/403で公開確認できず、確認できたのは寄附ベースの本規則のみ。', null, null, 'migration:361'),
  ('reg_ff01bb8086e3_joint_research', 'inst_catalog_ff01bb8086e3', '東京大学民間等共同研究取扱規則', 4, 'effective', '本文ページを実際に開き、平成9年12月16日評議会可決であることを確認した(現行の実施細則ページも規則集に併記されている)。', null, null, 'migration:361'),
  ('reg_0278b48721bd_conflict_of_interest', 'inst_catalog_0278b48721bd', '国立大学法人京都大学利益相反マネジメント規程', 4, 'effective', '京都大学規程集（kitei）の本文ページで実在を確認した。制定日・最終改正日はページ内に記載があるが今回は本文抜粋の確認のみで年月日までは未確認。', null, null, 'migration:361'),
  ('reg_0278b48721bd_side_job', 'inst_catalog_0278b48721bd', '国立大学法人京都大学に勤務する教職員の兼業に関する指針', 4, 'effective', '京都大学は兼業ルールを「規程」ではなく「指針」の形式で公開している（平成16年4月1日制定）。技術移転事業者役員兼業・研究成果活用企業役員等兼業など大学発ベンチャー関連の兼業許可類型を含むことをページ本文とPDFで確認した。', null, null, 'migration:361'),
  ('reg_0278b48721bd_ip_license', 'inst_catalog_0278b48721bd', '京都大学発明規程', 4, 'effective', '京都大学規程集で本文ページを確認した。職務発明の承継・帰属手続きを定める規程で、知的財産ポリシーに基づき制定されている。', null, null, 'migration:361'),
  ('reg_0278b48721bd_equity_stock_option', 'inst_catalog_0278b48721bd', '京都大学におけるライセンス等の対価として取得する株式等取扱規程', 4, 'effective', '本文を実際にフェッチして確認済み。平成24年3月6日総長裁定で制定、令和7年3月25日改正。研究成果ライセンス対価を株式等で取得する場合の取扱いを定める規程で、大学発ベンチャー企業の定義（第2条4号）を含むが、認定手続き自体は規定していない。', null, null, 'migration:361'),
  ('reg_0278b48721bd_joint_research', 'inst_catalog_0278b48721bd', '京都大学民間等共同研究取扱規程', 4, 'effective', '京都大学規程集で本文ページを確認した。民間企業等との共同研究の取扱手続きを定める規程。', null, null, 'migration:361'),
  ('reg_0278b48721bd_shared_equipment', 'inst_catalog_0278b48721bd', '京都大学国際科学イノベーション棟規程', 4, 'effective', '京都大学規程集で本文ページを確認した。ベンチャーインキュベーションセンター（レンタルオフィス・レンタルラボ）を含む国際科学イノベーション棟の使用に関する規程。宇治地区先端イノベーション拠点施設規程（w002RG00001240）も同種の施設規程として別途存在する。', null, null, 'migration:361'),
  ('reg_4dd74810eb71_conflict_of_interest', 'inst_catalog_4dd74810eb71', '大阪大学利益相反マネジメント規程', 4, 'effective', '大阪大学公式規程集(Reiki-Base)で本文を実際に確認。平成16年10月21日制定、直近改正は令和8年4月1日施行。産学官連携活動に伴う利益相反を大学として管理する規程であることを確認済み。', null, null, 'migration:361'),
  ('reg_4dd74810eb71_side_job', 'inst_catalog_4dd74810eb71', '国立大学法人大阪大学教職員兼業規程', 4, 'effective', '規程集内の同名ページ(reiki_honbun/u035RG00000513.html)はURLが404で現在アクセス不可（規程番号が振り直された可能性）だったため、大学公式サイトが直接配布するPDF本文で実在と内容を確認した。技術移転企業等の役員兼業に関する取扱いを含む。', null, null, 'migration:361'),
  ('reg_4dd74810eb71_ip_license', 'inst_catalog_4dd74810eb71', '大阪大学発明規程', 4, 'effective', '規程集内の同名ページ(reiki_honbun/u035RG00000474.html)はURLが404で現在アクセス不可（規程番号が振り直された可能性）だったため、大阪大学共創機構が公開するPDF本文（令和元年8月26日改正版）で実在と内容を確認。教職員が創作した知的財産権の帰属・実施許諾の基本事項を定める規程。', null, null, 'migration:361'),
  ('reg_4dd74810eb71_equity_stock_option', 'inst_catalog_4dd74810eb71', '国立大学法人大阪大学における寄附及びライセンス対価として取得する株式等の取扱いに関するガイドライン', 4, 'effective', '大阪大学共創機構サイトが公開するPDFで実在確認。平成21年4月27日制定。知財ライセンス対価等として大学が取得する株式・新株予約権の取扱いを定めるガイドラインで、正式な「規程」ではなくガイドライン扱い。別途「本学発ベンチャー企業支援に関する新株予約権等取得についてのガイドライン」の存在も検索で言及されたが、個別URLは未確認。', null, null, 'migration:361'),
  ('reg_4dd74810eb71_joint_research', 'inst_catalog_4dd74810eb71', '国立大学法人大阪大学共同研究規程', 4, 'effective', '大阪大学公式規程集(Reiki-Base)で本文を実際に確認。平成16年4月1日施行、直近改正は令和8年4月1日施行。大阪大学と学外機関との共同研究の実施・知的財産取扱いを定める規程。', null, null, 'migration:361'),
  ('reg_9ed928e1e75c_conflict_of_interest', 'inst_catalog_9ed928e1e75c', '国立大学法人東北大学利益相反マネジメント規程', 4, 'effective', 'g-reiki.net の東北大学規程集で本文を確認済み。平成21年4月から開示書提出等の運用が始まっている。最終改正日までは未確認。', null, null, 'migration:361'),
  ('reg_9ed928e1e75c_side_job', 'inst_catalog_9ed928e1e75c', '国立大学法人東北大学役員の兼業の取扱いに関する要項', 4, 'effective', '総長・理事・監事（常勤）役員の兼業を対象とする要項。一般教職員向けの「国立大学法人東北大学職員兼業規程」（平成16年規程第60号）も別途存在すると人事部ページで確認したが、g-reiki検索では本文の公開URLを特定できなかった（人事部の運用解説ページのみ確認: https://www.bureau.tohoku.ac.jp/jinji/open/kengyo/irai/unyo.htm）。', null, null, 'migration:361'),
  ('reg_9ed928e1e75c_ip_license', 'inst_catalog_9ed928e1e75c', '国立大学法人東北大学発明等規程', 4, 'effective', '発明・知的財産権の取扱いを定める規程。施行日は平成30年5月22日とWeb検索結果に表示されたが、原文での改正履歴までは未確認。', null, null, 'migration:361'),
  ('reg_9ed928e1e75c_equity_stock_option', 'inst_catalog_9ed928e1e75c', '国立大学法人東北大学における株式等の取得に関する規程', 4, 'effective', '本文をWebFetchで確認済み。原規程は平成31年4月1日施行、最終改正は令和6年7月9日。大学発ベンチャー等への出資・新株予約権取得の手続を規定。', null, null, 'migration:361'),
  ('reg_9ed928e1e75c_joint_research', 'inst_catalog_9ed928e1e75c', '国立大学法人東北大学共同研究取扱規程', 4, 'effective', 'g-reiki.net の東北大学規程集で存在を確認。改正日等の詳細本文までは今回未確認。', null, null, 'migration:361'),
  ('reg_ad192eae70e9_recognition', 'inst_catalog_ad192eae70e9', '名古屋大学発ベンチャー称号授与規程', 4, 'effective', '東海国立大学機構規則集（LegalCRUD公開版）で全文を確認。平成28年7月19日制定、直近改正は令和7年11月20日施行。名古屋大学発ベンチャー/学生ベンチャーの称号授与要件・審査委員会・支援内容(施設貸付、ロゴ使用等)を規定。', null, null, 'migration:361'),
  ('reg_ad192eae70e9_conflict_of_interest', 'inst_catalog_ad192eae70e9', '東海国立大学機構利益相反マネジメント規程', 4, 'effective', '東海国立大学機構(岐阜大学・名古屋大学の運営法人)規程として全文確認。附則で名古屋大学利益相反マネジメント専門委員会の設置に言及しており、名古屋大学にも適用される機構共通規程。令和4年4月1日施行版まで確認。', null, null, 'migration:361'),
  ('reg_ad192eae70e9_side_job', 'inst_catalog_ad192eae70e9', '東海国立大学機構役員及び職員の兼業・兼職に関する規程', 4, 'effective', '名古屋大学の公式ページ「教職員に対する兼業の依頼について」からリンクされている機構共通規程。第2条で機構長の許可権限を岐阜大学長・名古屋大学総長に委任する旨が明記され、名古屋大学教職員に適用されることを確認。令和2年4月1日施行。クロスアポイントメント制度の個別規程は未確認。', null, null, 'migration:361'),
  ('reg_ad192eae70e9_joint_research', 'inst_catalog_ad192eae70e9', '東海国立大学機構共同研究規程', 4, 'effective', '名古屋大学研究協力部研究事業課の共同研究案内ページからリンクされている機構共通規程。第2条の「部局」定義に名古屋大学の総長戦略本部・学部・研究科等が明記され、名古屋大学に適用されることを確認。令和2年4月1日制定、直近改正は令和7年3月31日(令和7年4月1日施行)。別途「名古屋大学共同研究受入要項」という実務要項もあるが未検証(PDFリンクのみ把握、内容未フェッチ)。', null, null, 'migration:361'),
  ('reg_ad192eae70e9_ip_license', 'inst_catalog_ad192eae70e9', '国立大学法人東海国立大学機構知的財産ポリシー', 4, 'effective', '名古屋大学学術研究・産学官連携推進本部の知的財産ページからリンクされたPDF(アクセス確認済み、HTTP200)。機構共通の知財ポリシー文書で、個別の知的財産権規程・実施許諾/ライセンス規程そのものではない可能性がある(PDF本文は未フェッチ、タイトルとリンク到達のみ確認)。より詳細な実施許諾規程は規則集内に別途あるかもしれないが今回未特定。', null, null, 'migration:361'),
  ('reg_c030bad12839_recognition', 'inst_catalog_c030bad12839', '九州大学における成果活用事業者への支援に伴い取得する株式等の取扱に関する規程', 4, 'effective', '九大は「大学発ベンチャー認定」という単独の認定規程ではなく、支援対象を「成果活用事業者」と定義するこの規程（および個別出資規程）で実質的な認定・取扱基準を定めている。規程集トップページと第4編産学連携・社会連携の一覧ページで規程名（H26規程124）を確認したが、g-reiki本文ページの直接URLは未特定のため一覧ページを一次情報として採用。', null, null, 'migration:361'),
  ('reg_c030bad12839_conflict_of_interest', 'inst_catalog_c030bad12839', '九州大学利益相反ポリシー', 4, 'effective', '2004年3月19日評議会承認、同年3月26日公表。大学公式トピックスページで正式名称・目的（大学発ベンチャー創出等の産学官連携活動に安心して取り組める体制整備）・承認日を確認。詳細な実施要項（利益相反マネジメント要項）は学内限定ページのみで一般公開URLは未確認。', null, null, 'migration:361'),
  ('reg_c030bad12839_side_job', 'inst_catalog_c030bad12839', '国立大学法人九州大学職員兼業規程', 4, 'effective', '制定平成16年度九大就規第18号、最終改正平成30年1月31日。大学公式サイトのPDF本文とg-reiki規程集の両方でURLを確認済み。兼業時間の上限（年360時間・月45時間）や学会役員無報酬兼業の包括許可など本文内容も確認した。', null, null, 'migration:361'),
  ('reg_c030bad12839_ip_license', 'inst_catalog_c030bad12839', '九州大学知的財産取扱規則', 4, 'effective', '制定平成16年4月1日、最終改正令和4年3月31日。産学官連携本部（AiRIMaQ）掲載PDFとg-reiki規程集本文の両方で内容（発明・特許権等の知的財産の定義と職員・学生の創出物の取扱い）を確認した。実施細則（発明者補償等）も別途存在。', null, null, 'migration:361'),
  ('reg_c030bad12839_equity_stock_option', 'inst_catalog_c030bad12839', '九州大学における個別研究プロジェクトに係る出資に関する規程', 4, 'effective', '令和6年度九大規程第15号。第4編産学連携・社会連携の規程一覧ページで規程名を確認、g-reiki本文ページも所在を確認（本文詳細URLは検索結果に記載されたものをそのまま使用）。上記の株式取扱規程と併せ、国立大学法人による大学発SUへの出資・株式取得の学内規程として2本の規程が存在する。', null, null, 'migration:361'),
  ('reg_c030bad12839_joint_research', 'inst_catalog_c030bad12839', '九州大学共同研究規則', 4, 'effective', '平成16年度九大規則第94号。実施細則（H16細則19）も別途あり。規程集第4編一覧ページとg-reiki検索結果の両方で規程名・番号を確認。共同研究部門規則・共同研究推進拠点規則という関連規則も同編に存在する。', null, null, 'migration:361'),
  ('reg_7c5298d724e8_recognition', 'inst_catalog_7c5298d724e8', '国立大学法人北海道大学における北大発認定スタートアップ企業称号授与規程', 4, 'effective', '北海道大学の公式規程データベース(Reiki-Base)で本文を確認済み。平成27年11月1日制定、令和6年1月1日最終改正・施行。8つの対象カテゴリと審査委員会、年1回の活動報告義務、称号取消し規定を含む。', null, null, 'migration:361'),
  ('reg_7c5298d724e8_conflict_of_interest', 'inst_catalog_7c5298d724e8', '国立大学法人北海道大学利益相反マネジメント規程', 4, 'effective', 'Reiki-Base掲載を検索で確認。産学官連携活動における利益相反の適切なマネジメントを目的とする規程。制定日・最終改正日は本文未取得のため未確認。', null, null, 'migration:361'),
  ('reg_7c5298d724e8_side_job', 'inst_catalog_7c5298d724e8', '国立大学法人北海道大学職員兼業規程', 4, 'effective', 'Reiki-Base掲載を検索で確認。平成16年海大達第104号制定。技術移転事業者役員・研究成果活用企業役員等の兼業は利益相反マネジメント規程に基づく役員兼業審査専門部会の審査を経て許可される旨を含む。最終改正日は本文未取得のため未確認。', null, null, 'migration:361'),
  ('reg_7c5298d724e8_ip_license', 'inst_catalog_7c5298d724e8', '国立大学法人北海道大学職務発明規程', 4, 'effective', '本文を確認済み。平成16年4月1日制定、令和6年1月1日最終改正・施行。職員等の発明・創作の取扱い、発明者の権利保護、発明補償金の枠組みを定める。', null, null, 'migration:361'),
  ('reg_7c5298d724e8_equity_stock_option', 'inst_catalog_7c5298d724e8', '国立大学法人北海道大学におけるライセンス等又はスタートアップ支援の対価として取得する株式等の取扱いに関する規程', 4, 'effective', '本文を確認済み。令和2年4月1日制定、令和6年1月1日最終改正・施行。ライセンス対価・スタートアップ支援対価として取得する株式・新株予約権の取扱いを規定。', null, null, 'migration:361'),
  ('reg_7c5298d724e8_joint_research', 'inst_catalog_7c5298d724e8', '国立大学法人北海道大学共同研究取扱規程', 4, 'effective', 'Reiki-Base掲載を検索で確認。学外機関との共同研究の取扱いを定める規程。制定日・最終改正日は本文未取得のため未確認。', null, null, 'migration:361'),
  ('reg_b8027b627d19_recognition', 'inst_catalog_b8027b627d19', '東京科学大学の研究成果等を活用したベンチャー企業への称号の授与に関する規則（令和6年規則第132号、東京科学大学認定ベンチャー）', 4, 'effective', '規則番号（令和6年規則第132号）と『東京科学大学認定ベンチャー』の名称は複数の検索結果で確認できたが、規程集(somuka.titech.ac.jp)上の本文URLは旧番号(x385RG00000424、東京工業大学時代の名称)が404で消えており現行IDを特定できなかった。制度を運用する東京科学大学イノベーションデザイン機構（Id機構）の公式『申請資格・手続き』ページは実際にブラウザで開いて内容を確認済み（2024年10月の大学統合に伴い制度が新設された旨を明記）。', null, null, 'migration:361'),
  ('reg_b8027b627d19_conflict_of_interest', 'inst_catalog_b8027b627d19', '国立大学法人東京科学大学産学連携活動の実施における利益相反マネジメント規則', 4, 'effective', '規程集ページを実際に開いて本文冒頭・公布日を確認済み。令和6年11月5日公布、規則第152号。', null, null, 'migration:361'),
  ('reg_b8027b627d19_side_job', 'inst_catalog_b8027b627d19', '国立大学法人東京科学大学役職員兼業規則（クロス・アポイントメント制度に関する規則を含む）', 4, 'effective', '役職員兼業規則本体はTMD側公開PDF（令和6年10月1日 規則第53号）で本文を確認。クロス・アポイントメント制度に関する規則は規程集ページを実際に開いて確認済み。', null, null, 'migration:361'),
  ('reg_b8027b627d19_ip_license', 'inst_catalog_b8027b627d19', '国立大学法人東京科学大学発明規則', 4, 'effective', '規程集ページを実際に開いて確認済み。職員就業規則本文中で『発明の内容、当該発明に係る知的財産権の帰属等の決定については、国立大学法人東京科学大学発明規則（令和6年規則第114号）の定めるところによる』と参照されている規則そのもの。実施許諾（ライセンス）契約自体の単独規程は見つからなかった。', null, null, 'migration:361'),
  ('reg_b8027b627d19_joint_research', 'inst_catalog_b8027b627d19', '国立大学法人東京科学大学共同研究取扱規則', 4, 'effective', '規程集ページの実在をWeb検索で確認（受託研究取扱規則、共同研究講座に関する規則も同じ規程集内に併存）。ページ本文までは開いていないが、規程集ドメイン内の同種ページは複数実際にアクセスして本物であることを確認済み。', null, null, 'migration:361'),
  ('reg_251654a7c128_recognition', 'inst_catalog_251654a7c128', '東京科学大学の研究成果等を活用したベンチャー企業への称号の授与に関する規則', 4, 'effective', '旧・東京工業大学の同名規則(規則不明)を統合大学化に伴い令和6年10月4日付規則第132号として東京科学大学規程集(旧titechドメイン)に再制定。本文を実際に開いて確認済み。', null, null, 'migration:361'),
  ('reg_251654a7c128_conflict_of_interest', 'inst_catalog_251654a7c128', '国立大学法人東京科学大学産学連携活動の実施における利益相反マネジメント規則', 4, 'effective', '本文を実際に開いて確認済み。目次章立てまで確認。', null, null, 'migration:361'),
  ('reg_251654a7c128_side_job', 'inst_catalog_251654a7c128', '国立大学法人東京科学大学役職員兼業規則', 4, 'effective', '本文を実際に開いて確認済み。制定令和6年10月1日規則第53号、最終改正令和8年5月15日規則第64号。クロス・アポイントメント制度に関する規則(x385RG00001775/x385RG00001814)も別途あり。', null, null, 'migration:361'),
  ('reg_251654a7c128_ip_license', 'inst_catalog_251654a7c128', '国立大学法人東京科学大学発明規則', 4, 'effective', '本文を実際に開いて確認済み。発明・ノウハウの取扱いを定める規則。関連して発明評価会議規程・職務発明報奨金支払要項も規程集に存在するが未詳読。', null, null, 'migration:361'),
  ('reg_251654a7c128_equity_stock_option', 'inst_catalog_251654a7c128', '国立大学法人東京科学大学ベンチャー支援出資事業モニタリング委員会要項', 4, 'effective', '出資そのものの規程ではなく、大学のベンチャー支援出資事業を監督するモニタリング委員会の設置要項。出資根拠となる個別規程は規程集内で未特定。本文は実際に開いて確認済み。', null, null, 'migration:361'),
  ('reg_251654a7c128_joint_research', 'inst_catalog_251654a7c128', '国立大学法人東京科学大学共同研究取扱規則', 4, 'effective', '本文を実際に開いて確認済み。令和7年7月1日から適用する改正あり。関連して共同研究講座に関する規則、ジョイントリサーチ講座規則も規程集に存在。', null, null, 'migration:361'),
  ('reg_251654a7c128_shared_equipment', 'inst_catalog_251654a7c128', '東京科学大学設備共用推進体設置要項', 4, 'effective', '大学発SU専用のインキュベーション施設利用規程ではなく、研究設備・機器の学内外共用化を推進する一般要項。本文を実際に開いて確認済み。SU向けの入居・施設利用に特化した規程は規程集内で未特定。', null, null, 'migration:361'),
  ('reg_7c4c7f7501f8_recognition', 'inst_catalog_7c4c7f7501f8', '国立大学法人筑波大学における大学発ベンチャーの支援に関する規程', 4, 'effective', 'PDF本文を実際に取得し全文確認済み。国際産学連携本部長が認定・支援を決定する仕組みで、認定委員会のような合議体は本規程内に規定なし（本部長単独判断）。', null, null, 'migration:361'),
  ('reg_7c4c7f7501f8_conflict_of_interest', 'inst_catalog_7c4c7f7501f8', '国立大学法人筑波大学利益相反規則', 4, 'effective', '利益相反・輸出管理マネジメント室の公式ページ経由でPDFリンクを確認。本文全文までは未取得だが、規則番号・制定日は公式ページ記載のものと一致。', null, null, 'migration:361'),
  ('reg_7c4c7f7501f8_side_job', 'inst_catalog_7c4c7f7501f8', '国立大学法人筑波大学職員兼業規程', 4, 'effective', '大学発ベンチャー支援規程第4条(4)から本規程が参照されており、実在を確認済み。本文全文は未取得。', null, null, 'migration:361'),
  ('reg_7c4c7f7501f8_ip_license', 'inst_catalog_7c4c7f7501f8', '国立大学法人筑波大学知的財産規則', 4, 'effective', '筑波大学規則集第5章（研究・産学連携）の公式ページで確認。関連して職務発明規程、研究ライセンス取扱規程、リサーチツール特許取扱規程、商標取扱規程も同章に存在。', null, null, 'migration:361'),
  ('reg_7c4c7f7501f8_equity_stock_option', 'inst_catalog_7c4c7f7501f8', '国立大学法人筑波大学が大学発ベンチャーからライセンス等を取得する場合の規程', 4, 'effective', '出資そのものではなくライセンス取得（対価としての新株予約権等取得を想定）に関する規程。筑波大学規則集第5章公式ページでタイトル・規程番号を確認済み、PDF本文は未取得。', null, null, 'migration:361'),
  ('reg_7c4c7f7501f8_joint_research', 'inst_catalog_7c4c7f7501f8', '国立大学法人筑波大学共同研究取扱規程', 4, 'effective', '筑波大学規則集第5章公式ページでタイトル・規程番号(平成16年法人規程第45号)を確認。国際産学連携本部の更新版PDF(令和6年改正)へのリンクも別途存在。', null, null, 'migration:361'),
  ('reg_77be07932123_recognition', 'inst_catalog_77be07932123', '国立大学法人神戸大学における大学発ベンチャーの認定に関する規程', 4, 'effective', '神戸大学規則集（office.kobe-u.ac.jp）で本文を確認済み。第3条第2項で「学術・社会共創機構社会共創部門及び共創事業部門イノベーションデザイン部会議」の議を経て学長が認定する旨を規定しており、recognition_committeeに相当する審議体はこの条文内で確認できたため単独規程は探していない。', null, null, 'migration:361'),
  ('reg_77be07932123_conflict_of_interest', 'inst_catalog_77be07932123', '神戸大学利益相反マネジメント規則', 4, 'effective', '神戸大学規則集で本文を確認済み。平成17年制定、令和8年6月30日改正（同年7月1日施行）の附則を確認した。', null, null, 'migration:361'),
  ('reg_77be07932123_side_job', 'inst_catalog_77be07932123', '国立大学法人神戸大学職員兼業規程', 4, 'effective', '神戸大学規則集で本文を確認済み。平成16年4月1日制定、令和4年3月29日改正（同年4月1日施行）。クロスアポイントメント制度の個別規程は今回の検索範囲では見つからず未確認。', null, null, 'migration:361'),
  ('reg_77be07932123_ip_license', 'inst_catalog_77be07932123', '国立大学法人神戸大学知的財産取扱規程', 4, 'effective', '神戸大学規則集で本文を確認済み。平成16年4月1日制定、令和8年6月30日最終改正。産官学連携本部の知的財産ポリシー紹介ページ（innov.kobe-u.ac.jp）とも整合。', null, null, 'migration:361'),
  ('reg_77be07932123_joint_research', 'inst_catalog_77be07932123', '神戸大学共同研究取扱規程', 4, 'effective', '神戸大学規則集で本文を確認済み。平成28年3月22日制定、令和8年6月30日最終改正（累計13回改正）。関連規則として「神戸大学共同研究講座及び共同研究部門規則」（平成26年11月28日制定、令和8年3月31日最終改正、https://www.office.kobe-u.ac.jp/plan-rules/act/110000640.html）も同カテゴリで確認済みだが、こちらは共同研究講座制度に特化した別規則のため主たる報告は取扱規程とした。', null, null, 'migration:361'),
  ('reg_c6d191a944c4_recognition', 'inst_catalog_c6d191a944c4', '国立大学法人千葉大学大学発ベンチャー企業等から対価として取得する株式等取扱規程', 4, 'effective', '「大学発ベンチャー」の認定という単独の規程・委員会手続きは規程集内に見当たらなかった。本規程の第2条第4項が『大学発ベンチャー企業等』の定義（研究成果を基に起業/共同研究実施/技術移転や出資等の支援を受けている、のいずれか該当）を定めており、事実上の認定基準として機能している。制定は平成31年4月1日、改正記録なし。', null, null, 'migration:361'),
  ('reg_c6d191a944c4_conflict_of_interest', 'inst_catalog_c6d191a944c4', '国立大学法人千葉大学利益相反マネジメントポリシー', 4, 'effective', '規程集（体系目次・学術研究）に掲載を確認。平成20年3月19日制定、以降の改正記録は本文からは確認できず。別途「利益相反委員会規程」(w149RG00000233)も同章に存在。', null, null, 'migration:361'),
  ('reg_c6d191a944c4_side_job', 'inst_catalog_c6d191a944c4', '国立大学法人千葉大学職員兼業規程', 4, 'effective', '規程集（就業規則章）に掲載を確認。平成16年4月1日制定、令和8年4月1日最終改正。本文にクロスアポイントメント制度に関する条項は含まれていない（別規程の可能性あり、今回は未確認）。', null, null, 'migration:361'),
  ('reg_c6d191a944c4_ip_license', 'inst_catalog_c6d191a944c4', '国立大学法人千葉大学知的財産ポリシー', 4, 'effective', '規程集（学術研究章）に掲載を確認。令和4年4月1日制定、以降の改正記録は本文からは確認できず。実施許諾（ライセンス）の個別規程は別途ある可能性があるが今回は未確認。', null, null, 'migration:361'),
  ('reg_c6d191a944c4_equity_stock_option', 'inst_catalog_c6d191a944c4', '国立大学法人千葉大学における出資に関する規程', 4, 'effective', '産業競争力強化法に基づく認定特定研究成果活用支援事業者への出資を規定。令和6年7月1日制定、改正記録なし。株式取得（対価としての株式取扱）は上記recognitionの規程が別途カバー。', null, null, 'migration:361'),
  ('reg_c6d191a944c4_joint_research', 'inst_catalog_c6d191a944c4', '国立大学法人千葉大学共同研究取扱規程', 4, 'effective', '規程集（学術研究章）に掲載を確認。平成16年4月1日制定、令和7年5月1日最終改正（令和6年4月1日から適用）。同章に「共同研究講座及び共同研究部門規程」も別途あり。', null, null, 'migration:361'),
  ('reg_c6d191a944c4_support_rules', 'inst_catalog_c6d191a944c4', '国立大学法人千葉大学関連スタートアップ支援に関する規程', 4, 'effective', '規程集（学術研究章）に掲載を確認。令和8年4月1日制定・施行、改正記録なし。大学の研究成果活用や教職員起業等の条件に該当する「関連スタートアップ」への施設貸与・登記住所提供・成長支援相談等を規定した支援細則。', null, null, 'migration:361'),
  ('reg_b23ba1a5f5b4_recognition', 'inst_catalog_b23ba1a5f5b4', 'ベンチャー企業に対する大学知的財産利用認定に関する要項', 4, 'effective', 'PDF本文を実際に取得し全文確認済み。2015年5月12日理事・副学長決裁で制定、2020年8月5日施行(2020年4月1日適用)の改正版が現行。学長が広島大学学術・社会連携室発明審査会(認定委員会に相当)へ諮り認定する枠組み。規程集PDFとしての正式な「規程」名ではなく「要項」だが、大学発ベンチャー認定制度の一次資料として機能している。', null, null, 'migration:361'),
  ('reg_b23ba1a5f5b4_conflict_of_interest', 'inst_catalog_b23ba1a5f5b4', '広島大学利益相反管理に関する規則', 4, 'effective', '規程集(LegalCRUD)ページで全条文(6章20条+附則)を確認済み。平成20年9月16日規則第166号で制定、令和7年4月1日規則第67号が最新改正。ページ末尾に「学外非公開」表示があり学内ポータル「いろは」に完全版があるとの案内だが、本ページ自体は条文が読める形で公開されている。別途「広島大学臨床研究に係る利益相反管理に関する規則」(平成21年7月21日規則第120号)も同一サイトで確認済み。', null, null, 'migration:361'),
  ('reg_b23ba1a5f5b4_side_job', 'inst_catalog_b23ba1a5f5b4', '広島大学職員兼業規則', 4, 'effective', '規程集(LegalCRUD)ページで正式名称・制定日・改正日を確認済み。平成16年4月1日規則第89号で制定、令和3年3月22日規則第46号(令和3年4月1日施行)が最新改正。別途大学公式サイトに実務向け「兼業の手引き」(2025年12月改訂版PDF)もあるが、規程本体はこちらのURL。', null, null, 'migration:361'),
  ('reg_b23ba1a5f5b4_joint_research', 'inst_catalog_b23ba1a5f5b4', '広島大学共同研究取扱規則', 4, 'effective', '規程集(LegalCRUD)ページで正式名称・制定日・改正日を確認済み。平成18年3月14日規則第18号で制定、令和8年2月25日規則第7号(令和8年4月1日施行)が最新改正。条文本文は「学外非公開、学内ポータル『いろは』で確認」の制限あり(目次・改正履歴は公開)。', null, null, 'migration:361'),
  ('reg_faf4fe8290f5_recognition', 'inst_catalog_faf4fe8290f5', '岡山大学発ベンチャー（称号付与制度）', 4, 'effective', '「岡山大学ベンチャー支援サイト」で称号付与制度の存在と概要（知財優遇・施設利用優遇・住所登記可）を確認したが、根拠規程本文（要項・規程PDF）は公開ページからは辿れず、非公開または問い合わせ経由の可能性が高い。令和3年度創設、令和7年度も称号授与式を実施しており制度は継続稼働中。', null, null, 'migration:361'),
  ('reg_faf4fe8290f5_conflict_of_interest', 'inst_catalog_faf4fe8290f5', '国立大学法人岡山大学利益相反マネジメント規程', 4, 'effective', '研究・イノベーション共創機構の利益相反マネジメントページからPDF本文を直接取得し全文を確認済み。平成30年4月17日岡大規程第39号で制定、直近改正は令和7年9月30日施行（令和7年8月19日適用）。個人・組織双方の利益相反管理体制、委員会、アドバイザー制度を規定。', null, null, 'migration:361'),
  ('reg_faf4fe8290f5_side_job', 'inst_catalog_faf4fe8290f5', '国立大学法人岡山大学職員兼業規程', 4, 'effective', '大学公式規程データベース（Reiki-Base）の本文ページをWebFetchで確認。平成16年4月1日岡大規程第12号で制定、直近改正は令和8年3月31日規程第42号（令和8年4月1日施行）で現行有効。営利企業兼業・自営兼業・非営利企業兼業の3類型と学長承認手続きを規定。', null, null, 'migration:361'),
  ('reg_faf4fe8290f5_ip_license', 'inst_catalog_faf4fe8290f5', '国立大学法人岡山大学職務発明等取扱規程', 4, 'effective', 'Reiki-Base本文ページで確認。平成16年4月1日岡大規程第17号で制定、直近改正は令和6年3月29日規程第38号（令和6年4月1日施行）で現行有効。職務発明の届出・審査・大学承継・補償金支払い手続きを規定。なお別途ORSDサイトに「研究ライセンスポリシー」（平成19年制定）もあるが、これは非営利研究間の実施許諾に限定される内容のため、より一般的な知財規程として職務発明等取扱規程を採用した。', null, null, 'migration:361'),
  ('reg_faf4fe8290f5_joint_research', 'inst_catalog_faf4fe8290f5', '岡山大学共同研究取扱規程', 4, 'effective', 'Reiki-Base本文ページで確認。平成16年4月1日岡大規程第39号で制定、直近改正は令和7年8月19日規程第112号で現行有効。民間機関等との共同研究の取扱いに関する基本事項を規定。', null, null, 'migration:361'),
  ('reg_be0174a565d7_recognition', 'inst_catalog_be0174a565d7', '国立大学法人九州工業大学における大学発スタートアップの支援に関する規程(SU支援規程)', 4, 'effective', '2024年11月制定の規程本文が九州工業大学規則集(bap.jimu.kyutech.ac.jp)に存在する可能性が高いが、当該サイトはJS制御のフィルタ検索でありWebFetch/WebSearchでは直接のURLを特定できなかった。規程の存在と制定時期・「九工大発スタートアップ」称号付与の枠組みは、社会実装本部未来思考実証センターが2026年3月1日付で公開した支援メニュー説明資料(PDF)で確認済み。', null, null, 'migration:361'),
  ('reg_be0174a565d7_conflict_of_interest', 'inst_catalog_be0174a565d7', '九州工業大学利益相反マネジメント規程', 4, 'effective', '規則集(bap.jimu.kyutech.ac.jp)の当該規程ページで確認。産学官連携活動における利益相反管理を目的とする規程。', null, null, 'migration:361'),
  ('reg_be0174a565d7_side_job', 'inst_catalog_be0174a565d7', '国立大学法人九州工業大学職員兼業規程', 4, 'effective', '規則集で本文所在を確認。クロスアポイントメント制度への明示的言及は規程本文中には確認できなかった。', null, null, 'migration:361'),
  ('reg_be0174a565d7_ip_license', 'inst_catalog_be0174a565d7', '九州工業大学職務発明取扱規程', 4, 'effective', '発明の届出義務、権利の帰属(原則大学帰属)、出願後の取り扱い、特許補償を定める規程。実施許諾(ライセンス)単独の規程は別途確認できず、この規程内に含まれる可能性がある。関連する「職務発明取扱細則」も同ページ群に存在。', null, null, 'migration:361'),
  ('reg_be0174a565d7_equity_stock_option', 'inst_catalog_be0174a565d7', '大学発スタートアップ支援における新株予約権取得の枠組み(SU支援規程の一部)', 2, 'review', '独立の出資・新株予約権取得規程は確認できなかった。SU支援規程に基づき『支払いの一部を新株予約権の取得に代える等、柔軟な対応を行うことを想定(詳細は検討中)』との記載が2026年3月1日付資料にあり、制度設計はまだ完了していない段階と読める。', null, null, 'migration:361'),
  ('reg_be0174a565d7_joint_research', 'inst_catalog_be0174a565d7', '九州工業大学共同研究取扱要項', 4, 'effective', '共同研究契約の締結手続き、経費納入、実施報告義務、研究成果譲渡対価の配分比率(研究室70%/大学30%)、事業化成功報酬料率(経常利益の1%以上)などを規定。', null, null, 'migration:361'),
  ('reg_yamaguchi_conflict_of_interest', 'inst_yamaguchi', '国立大学法人山口大学利益相反・責務相反マネージメント委員会規則', 4, 'effective', '山口大学規則集（学内規程データベース）で本文を確認。令和8年3月31日規則第77号改正まで反映され現行有効。別途「利益相反・責務相反マネージメントポリシー」（規則第47号）も同規則集に存在。', null, null, 'migration:361'),
  ('reg_yamaguchi_ip_license', 'inst_yamaguchi', '国立大学法人山口大学知的財産ポリシー', 4, 'effective', '規則集で本文確認。令和7年4月1日施行の改正版が現行。同規則集内に「職務発明等規則」「補償金等に関する規則・細則」「公的資金による研究成果の実施権許諾に関する規則」も別途存在。／関連文書: 国立大学法人山口大学ライセンスポリシー も版履歴として確認済み。', null, null, 'migration:361'),
  ('reg_yamaguchi_side_job', 'inst_yamaguchi', '国立大学法人山口大学職員兼業規則', 4, 'effective', '規則集で本文確認。令和7年4月1日施行の改正版が現行。クロスアポイントメント制度への明示的言及は本文中に確認できなかったが、研究成果活用企業役員等を兼ねる場合の休職規定（第11条第4項）はある。役員兼業規則・営利企業役員等兼業規則・自営兼業規則が別規則として並存。', null, null, 'migration:361'),
  ('reg_yamaguchi_joint_research', 'inst_yamaguchi', '国立大学法人山口大学共同研究取扱規則', 4, 'effective', '規則集で本文確認。昭和60年制定、令和7年4月1日施行の改正版が現行。別途「受託研究取扱規則」「共同研究講座規則」も規則集に存在。', null, null, 'migration:361'),
  ('reg_yamaguchi_shared_equipment', 'inst_yamaguchi', '国立大学法人山口大学における施設の有効活用に関する規則', 4, 'effective', '規則集で本文確認。令和7年4月1日施行の改正版が現行。大学発SU向けインキュベーション施設利用を明示した条項は本文中に確認できず、汎用的な学内スペース有効活用規則（若手研究者スペース等）にとどまる。専用の起業支援施設規程は未確認。', null, null, 'migration:361'),
  ('reg_3a28a90ae0d9_recognition', 'inst_catalog_3a28a90ae0d9', '国立大学法人徳島大学における大学発ベンチャーの認定に関する規則', 4, 'effective', '平成28年度規則第21号として制定、2021年8月1日改正版がPDFで産官学連携センターのページに公開されている。規程集(reiki_honbun)側の個別ページは検索で直接特定できず、条文の引用（他規則からの参照）でのみ規則番号を確認した。', null, null, 'migration:361'),
  ('reg_3a28a90ae0d9_equity_stock_option', 'inst_catalog_3a28a90ae0d9', '国立大学法人徳島大学における認定大学発ベンチャーから本学の収益を伴う事業の対価として取得する株式等取扱規則', 4, 'effective', '規程集(reiki_honbun)で本文ページを直接確認した。認定大学発ベンチャーからの株式・新株予約権取得の取扱いを定める規則。', null, null, 'migration:361'),
  ('reg_3a28a90ae0d9_conflict_of_interest', 'inst_catalog_3a28a90ae0d9', '国立大学法人徳島大学利益相反管理規則', 4, 'effective', '規程集(reiki_honbun)で本文ページを確認。利益相反アドバイザー・コーディネーターの設置や兼業審査等の運用が定められている。', null, null, 'migration:361'),
  ('reg_3a28a90ae0d9_side_job', 'inst_catalog_3a28a90ae0d9', '国立大学法人徳島大学職員兼業規則', 4, 'effective', '規程集(reiki_honbun)で本文ページを確認した。クロスアポイントメント固有の別規則は検索範囲内で見つからなかった。', null, null, 'migration:361'),
  ('reg_3a28a90ae0d9_ip_license', 'inst_catalog_3a28a90ae0d9', '国立大学法人徳島大学職務発明規則', 4, 'effective', '規程集(reiki_honbun)で本文ページを確認。職務発明の帰属・届出手続を定める規則で、実施許諾（ライセンス）単独の規程は別途見当たらなかった。', null, null, 'migration:361'),
  ('reg_3a28a90ae0d9_joint_research', 'inst_catalog_3a28a90ae0d9', '国立大学法人徳島大学共同研究取扱規則', 4, 'effective', '規程集(reiki_honbun)で本文ページを確認。2020年10月1日施行で産学官連携による共同研究強化ガイドラインを踏まえ改正済みとの情報あり（改正版そのものの日付はページ内で未確認）。', null, null, 'migration:361'),
  ('reg_3a28a90ae0d9_shared_equipment', 'inst_catalog_3a28a90ae0d9', '研究支援・産官学連携センター施設管理規則（地域共同インキュベーション研究室・ベンチャービジネス育成研究室の利用）', 4, 'effective', '産官学連携センターのページで規則PDFと関連書式一式（利用申請書、覚書、使用心得等）を確認した。入居対象は徳島大学教員、入居期間3年以内、年間6,000円/㎡。規程集(reiki_honbun)側の統合ページではなく、センター独自の施設ページで公開されている。', null, null, 'migration:361'),
  ('reg_515e2fa03507_recognition', 'inst_catalog_515e2fa03507', '長崎大学における長崎大学発ベンチャーの称号授与に関する規程', 4, 'effective', 'g-reiki.netの規程集本文を実際に開いて確認。令和4年3月28日制定（規程第34号）、令和8年3月31日改正（規程第33号）まで確認できた現行規程。対象企業の定義、有効期間3年（更新可）、申請から研究開発推進機構運営委員会審議までの手続、取消事由を規定。', null, null, 'migration:361'),
  ('reg_515e2fa03507_conflict_of_interest', 'inst_catalog_515e2fa03507', '長崎大学利益相反委員会規則', 4, 'effective', 'g-reiki.net本文を確認。平成16年4月1日制定（規則第58号）、最新施行は令和8年4月1日（令和8年3月31日規則第20号改正）。利益相反・責務相反を審議する委員会の組織運営を規定。別途「長崎大学利益相反マネジメントポリシー」PDFも研究開発推進機構サイトに存在するが未確認（http://www.mh.nagasaki-u.ac.jp/research/rinsho/rieki-sohan/management_policy.pdf）。', null, null, 'migration:361'),
  ('reg_515e2fa03507_side_job', 'inst_catalog_515e2fa03507', '長崎大学営利企業役員等兼業規程', 4, 'effective', 'g-reiki.net本文を確認。平成16年4月1日制定（規程第37号）、令和8年3月31日改正（規程第33号）まで確認。技術移転事業・研究成果活用事業の役員等兼業を対象とし、専門部会審査、6か月ごとの報告義務、兼業終了後2年間の利害関係業務従事禁止を規定。一般教職員向けの「長崎大学職員兼業規程」（平成16年規程第45号、令和6年10月1日改正）も別途確認済み。', null, null, 'migration:361'),
  ('reg_515e2fa03507_ip_license', 'inst_catalog_515e2fa03507', '長崎大学職務発明規程', 4, 'effective', 'g-reiki.net本文を確認。平成16年4月1日制定（規程第73号）、平成30年6月26日改正（規程第36号）まで確認。知的財産権の大学帰属、発明認定手続、登録・実施・譲渡補償金制度を規定。研究開発推進機構サイトには「長崎大学知的財産ポリシー」も別途あり（https://www.ipc.nagasaki-u.ac.jp/02_policy_01.html、未フェッチ確認）。', null, null, 'migration:361'),
  ('reg_515e2fa03507_joint_research', 'inst_catalog_515e2fa03507', '長崎大学共同研究取扱規程', 4, 'effective', 'g-reiki.net本文を確認。平成16年4月1日制定（規程第66号）、令和7年4月1日施行版まで13回の改正を経て現行。共同研究の申込・契約手続、経費負担（間接経費標準10%）、知財帰属、成果公表を規定。上位規程の「長崎大学共同研究規程」（x893RG00000159）も同じ機構サイトに掲載あり、内容は未フェッチ確認。', null, null, 'migration:361'),
  ('reg_355ac37a0d09_recognition', 'inst_catalog_355ac37a0d09', '国立大学法人信州大学における大学発スタートアップの認定に関する規程', 4, 'effective', '平成30年3月28日制定（信州大学規程第158号）、令和5年度規程第112号により改正され令和6年4月1日施行の現行版を規程集ページで実際に確認した。認定対象4類型（大学帰属知財ベンチャー、大学発研究成果・技術ベンチャー、教職員/学生が創業者・設立時役員のベンチャー、学長が特に認めるもの）を含む。', null, null, 'migration:361'),
  ('reg_355ac37a0d09_conflict_of_interest', 'inst_catalog_355ac37a0d09', '国立大学法人信州大学産学官連携利益相反マネジメント規程', 4, 'effective', '平成18年3月30日制定（信州大学規程第83号）。関連して令和7年3月18日に教育研究評議会承認の利益相反マネジメントポリシーも別途公開されているのを検索結果で確認した（本文までは未確認）。', null, null, 'migration:361'),
  ('reg_355ac37a0d09_side_job', 'inst_catalog_355ac37a0d09', '国立大学法人信州大学職員兼業規程', 4, 'effective', '平成16年4月7日制定（信州大学規程第47号）を規程集ページで実際に確認した。別途「役員兼業規程」「職員兼業許可等実施細則」も規程集に存在するが本文未確認。', null, null, 'migration:361'),
  ('reg_355ac37a0d09_ip_license', 'inst_catalog_355ac37a0d09', '国立大学法人信州大学知的財産規程', 4, 'effective', '平成16年4月1日制定（信州大学規程第33号）。発明者の権利保障と知的財産権の管理・活用の基本方針を定めるものと本文で確認した。実施許諾（ライセンス）の細則が別文書に分かれているかは未確認。', null, null, 'migration:361'),
  ('reg_355ac37a0d09_joint_research', 'inst_catalog_355ac37a0d09', '信州大学共同研究取扱規程', 4, 'effective', '平成16年4月1日制定（信州大学規程第34号）を規程集ページで実際に確認した。', null, null, 'migration:361'),
  ('reg_96888e99eb1a_recognition', 'inst_catalog_96888e99eb1a', '静岡大学における静岡大学発ベンチャーの称号授与に関する規則', 4, 'effective', '静岡大学規則集（reiki.adb.shizuoka.ac.jp）の産学連携支援課分野およびイノベーション社会連携推進機構分野で公開されている一次規程本文を実際に開いて条文を確認した。認定要件・審査委員会（機構長ほかで構成）・称号授与手続・取消要件まで規定されている現行規則。', null, null, 'migration:361'),
  ('reg_96888e99eb1a_conflict_of_interest', 'inst_catalog_96888e99eb1a', '国立大学法人静岡大学利益相反マネジメント規則', 4, 'effective', '同規則集の産学連携支援課分野で本文を確認。教職員等の産学官連携活動（兼業・共同研究・受託研究等）に伴う利益相反マネジメントを規定する現行規則。', null, null, 'migration:361'),
  ('reg_96888e99eb1a_side_job', 'inst_catalog_96888e99eb1a', '国立大学法人静岡大学教職員兼業規程', 4, 'effective', '静岡大学規則集の全文カタログには本規程名が見当たらず（人事系の非公開区分の可能性）、代わりに産学連携ページ「本学教職員への兼業依頼」からリンクされているPDF原文を直接開いて確認した。役員兼業は開始4か月前手続きが必要と案内されている。クロスアポイントメント制度規程（国立大学法人静岡大学クロスアポイントメント制度に関する規程、平成29年3月29日規程第328号）は規則集内 https://reiki.adb.shizuoka.ac.jp/act/ 配下の人事課分野に別途存在するが、本findingでは主たる兼業規程を優先して報告した。', null, null, 'migration:361'),
  ('reg_96888e99eb1a_ip_license', 'inst_catalog_96888e99eb1a', '静岡大学職務発明規則', 4, 'effective', '同規則集の産学連携支援課分野で本文を確認。静岡大学知的財産ポリシーに基づき教職員等の発明・ノウハウ等の帰属・実施許諾等を規定する現行規則。', null, null, 'migration:361'),
  ('reg_96888e99eb1a_equity_stock_option', 'inst_catalog_96888e99eb1a', '国立大学法人静岡大学における大学発ベンチャー企業支援を目的とした株式等取得に関する規則', 4, 'effective', '同規則集の産学連携支援課分野で本文を確認。国立大学法人静岡大学株式等管理規則第12条に基づき、称号授与を受けた大学発ベンチャーに対する株式・新株予約権取得の審査体制（ベンチャー企業株式等審査会）まで具体的に規定している現行規則。', null, null, 'migration:361'),
  ('reg_96888e99eb1a_joint_research', 'inst_catalog_96888e99eb1a', '静岡大学共同研究取扱規則', 4, 'effective', '同規則集の産学連携支援課分野で本文を確認。昭和60年制定、令和5年2月15日規則第41号まで継続改正されている現行規則。', null, null, 'migration:361'),
  ('reg_96888e99eb1a_shared_equipment', 'inst_catalog_96888e99eb1a', '静岡大学イノベーション社会連携推進機構管理施設利用規則', 4, 'effective', '同規則集で本文を確認。イノベーション社会連携推進機構が管理する施設（新規事業創出プロジェクト・共同研究等に利用可）の利用資格・申請手続・経費負担等を規定する現行規則。ベンチャー専用施設に限定した規程ではないが、新規事業創出・知財活用目的の利用が明記されており該当カテゴリの実質規程として報告する。', null, null, 'migration:361'),
  ('reg_96888e99eb1a_support_rules', 'inst_catalog_96888e99eb1a', '静岡大学イノベーション社会連携推進機構規則', 4, 'effective', '同規則集で本文を確認。産学連携推進部門の所掌業務として「大学発ベンチャーの起業及び育成支援事業の推進」「起業家教育の実践」を明記しており、SU支援の組織・機能を定める規程として報告する。認定委員会（recognition_committee）は上記「称号授与に関する規則」第4条に審査委員会として同梱されているため、別立てのfindingは作成していない。', null, null, 'migration:361'),
  ('reg_75953cdd2d43_recognition', 'inst_catalog_75953cdd2d43', '国立大学法人群馬大学における大学発ベンチャーの認定及び支援に関する規程', 4, 'effective', '群馬大学規則集（第6章 研究）内でPDF原文を直接確認した。令和6年8月1日制定・施行、単発の初版でまだ改正履歴なし。認定要件、称号授与、支援措置（施設貸与、知財優遇、株式・新株予約権での対価受領等）、取消要件まで規定。', null, null, 'migration:361'),
  ('reg_75953cdd2d43_conflict_of_interest', 'inst_catalog_75953cdd2d43', '国立大学法人群馬大学利益相反マネジメント規程', 4, 'effective', '群馬大学規則集（第7章 社会連携）内でPDF原文を直接確認した。平成17年12月1日制定、直近改正は令和7年10月1日。利益相反マネジメント体制、個人・組織双方の対策手続を規定。', null, null, 'migration:361'),
  ('reg_75953cdd2d43_side_job', 'inst_catalog_75953cdd2d43', '国立大学法人群馬大学教職員兼業規則', 4, 'effective', '群馬大学規則集（第2章 総務/就業規則）内でPDF原文を直接確認した。平成16年4月1日制定、直近改正は令和6年4月1日。産学官連携活動に伴う役員兼業・技術移転事業者役員兼業等の許可基準を含む。大学発ベンチャー認定規程からも参照される規則。', null, null, 'migration:361'),
  ('reg_75953cdd2d43_ip_license', 'inst_catalog_75953cdd2d43', '国立大学法人群馬大学教職員等の知的財産権の譲渡に関する細則', 4, 'effective', '群馬大学規則集（第6章 研究）内でPDF原文を直接確認した。平成16年7月1日制定、直近改正は平成28年4月1日。職務発明等規則に基づく知財譲渡・承継・名義変更手続を規定。より上位の「職務発明等規則」本体の規程集内URLは未特定（本細則から参照されるのみ確認）。', null, null, 'migration:361'),
  ('reg_75953cdd2d43_joint_research', 'inst_catalog_75953cdd2d43', '国立大学法人群馬大学共同研究取扱規程', 4, 'effective', '群馬大学規則集（第6章 研究）内でPDF原文を直接確認した。平成16年4月1日制定、直近改正は令和6年4月1日。共同研究の定義、研究代表者・共同研究員の扱い、知的財産権の取扱いを規定。', null, null, 'migration:361'),
  ('reg_75953cdd2d43_shared_equipment', 'inst_catalog_75953cdd2d43', '研究設備・機器の共用に関する基本方針', 4, 'effective', '研究・産学連携推進機構のポリシー掲載ページからPDFリンクを確認（規程集本体ではなく研究推進部門の方針文書）。制定日等の内容は未確認、URL存在のみ確認済み。大学発SU向け専用の設備共用制度としての明記は未確認。', null, null, 'migration:361'),
  ('reg_634ea0a5f19c_recognition', 'inst_catalog_634ea0a5f19c', '国立大学法人山形大学における大学発ベンチャーの認定等に関する規程', 4, 'effective', '公式規程集で本文を確認済み。令和4年9月28日制定、令和5年5月10日施行。研究戦略企画本部の審議を経て学長が認定・称号授与。施設貸与や特許使用優遇等の支援を最大5年間（延長可）。', null, null, 'migration:361'),
  ('reg_634ea0a5f19c_equity_stock_option', 'inst_catalog_634ea0a5f19c', '国立大学法人山形大学における大学発ベンチャー企業を対象とした収益を伴う事業の対価として取得する株式等取扱規程', 4, 'effective', '公式規程集で本文を確認済み。平成26年10月1日制定、直近改正は令和4年9月28日（同年10月1日施行）。', null, null, 'migration:361'),
  ('reg_634ea0a5f19c_side_job', 'inst_catalog_634ea0a5f19c', '国立大学法人山形大学職員の兼業に関する規程の運用について', 4, 'effective', '公式規程集で本文を確認済み。技術移転兼業・研究成果活用兼業など大学発ベンチャー関連の兼業類型を含む運用文書。兼業に関する規程本体（基準となる規程番号）そのものの単独公開ページは今回の調査では特定できず、運用文書を一次情報として採用。', null, null, 'migration:361'),
  ('reg_634ea0a5f19c_ip_license', 'inst_catalog_634ea0a5f19c', '国立大学法人山形大学職務発明規程', 4, 'effective', '公式規程集で本文を確認済み。職務発明の定義・帰属・知的財産の取扱いを規定。', null, null, 'migration:361'),
  ('reg_5617b63909d5_recognition', 'inst_catalog_5617b63909d5', '山梨大学発ベンチャーの認定制度', 4, 'effective', '令和2年に認定制度を制定し、複数の認定第1号称号記授与式を大学公式サイトで確認済み（研究成果ベンチャー・共同研究ベンチャー・技術移転ベンチャー・学生ベンチャー・関連ベンチャーの5分類）。ただし規程本文PDF自体の単独公開URLは今回の調査では特定できず、公式発表ページを一次情報として採用。', null, null, 'migration:361'),
  ('reg_cbd79e6a149d_recognition', 'inst_catalog_cbd79e6a149d', '国立大学法人茨城大学の研究成果等を活用したベンチャー企業への称号の授与に関する内規', 4, 'effective', '研究・産学官連携機構(iRIC)の企業向けページ経由で規程集(houki.admb.ibaraki.ac.jp)本文を確認。平成18年4月20日制定、令和4年3月28日改正(令和4年4月1日施行)で現行有効。', null, null, 'migration:361'),
  ('reg_cbd79e6a149d_equity_stock_option', 'inst_catalog_cbd79e6a149d', '国立大学法人茨城大学におけるベンチャー企業を対象とした収益を伴う事業の対価として取得する株式等の取扱いに関する規程', 4, 'effective', '認定内規と同じiRICポリシー・規程集ページから規程集本文を確認。令和5年2月22日制定、令和8年6月25日改正(令和8年7月1日施行)で現行有効。', null, null, 'migration:361'),
  ('reg_cbd79e6a149d_conflict_of_interest', 'inst_catalog_cbd79e6a149d', '国立大学法人茨城大学利益相反マネジメント規程', 4, 'effective', '規程集本文を直接確認。平成22年6月23日制定、令和8年6月25日改正(令和8年7月1日施行)で現行有効。同ページ群に「国立大学法人茨城大学利益相反ポリシー」も別途あり(未取得)。', null, null, 'migration:361'),
  ('reg_cbd79e6a149d_side_job', 'inst_catalog_cbd79e6a149d', '国立大学法人茨城大学兼業実施基準', 4, 'effective', '規程集本文を直接確認。平成16年4月1日制定、令和7年5月22日改正で現行有効。教職員向け兼業案内ページ(ibaraki.ac.jp/m/enterprise/sideline)からもリンクされている。クロスアポイントメント制度の専用規程は今回確認できなかった。', null, null, 'migration:361'),
  ('reg_cbd79e6a149d_ip_license', 'inst_catalog_cbd79e6a149d', '国立大学法人茨城大学知的財産ポリシー', 4, 'effective', '規程集本文を直接確認。平成17年3月17日制定、令和2年3月6日改正で現行有効。同ページ群に「国立大学法人茨城大学職務発明規程」(houki.admb.ibaraki.ac.jp/lc25/act/110000063.html、未取得)もあり実施許諾の詳細はそちらに含まれる可能性がある。', null, null, 'migration:361'),
  ('reg_cbd79e6a149d_joint_research', 'inst_catalog_cbd79e6a149d', '茨城大学共同研究取扱規程', 4, 'effective', '規程集本文を直接確認。平成27年3月31日制定、令和8年6月25日改正(令和8年7月1日施行)で現行有効。', null, null, 'migration:361'),
  ('reg_5fc4daca90d2_recognition', 'inst_catalog_5fc4daca90d2', '国立大学法人宇都宮大学における大学発ベンチャーに関する規程', 4, 'effective', '規程集(legalcrud)の当該規程本文を実際に開いて確認。令和7年規程第62号として令和7年11月1日施行、令和8年規程第66号(令和8年4月1日施行)で改正済み。認定要件6項目と認定委員会設置(第3条)を確認済み。大学公式サイトの産学連携ページ(spinoff.php)にも認定ベンチャー一覧あり。', null, null, 'migration:361'),
  ('reg_5fc4daca90d2_recognition_committee', 'inst_catalog_5fc4daca90d2', '国立大学法人宇都宮大学における大学発ベンチャーに関する規程(第3条 宇都宮大学発ベンチャー認定委員会)', 4, 'effective', '単独の内規ではなく、大学発ベンチャー規程第3条に認定委員会の設置根拠が同梱されている形。recognitionと同一URL・同一本文で確認済み。', null, null, 'migration:361'),
  ('reg_5fc4daca90d2_conflict_of_interest', 'inst_catalog_5fc4daca90d2', '国立大学法人宇都宮大学利益相反マネジメント規程', 4, 'effective', '規程本文を実際に確認。平成24年10月9日制定、令和8年規程第69号(令和8年4月1日施行)まで改正が続いており現行有効。', null, null, 'migration:361'),
  ('reg_5fc4daca90d2_side_job', 'inst_catalog_5fc4daca90d2', '国立大学法人宇都宮大学職員兼業規程', 4, 'effective', '規程本文を確認。平成16年制定、令和8年規程第81号(令和8年4月15日施行)まで改正され現行有効。関連して職員営利企業役員等兼業審査委員会規程(act/110000091.html)、クロスアポイントメント制度に関する規程(act/110000804.html、平成30年規程第16号)も同カテゴリで確認済み(未添付・必要なら追加可)。', null, null, 'migration:361'),
  ('reg_5fc4daca90d2_ip_license', 'inst_catalog_5fc4daca90d2', '宇都宮大学職務発明規程', 4, 'effective', '規程本文を確認。知的財産権の大学承継(第3条)と実施許諾(ライセンス、第21条、附属の「研究ライセンスポリシー」act/110000351.htmlに接続)を規定。令和6年規程第99号(令和6年4月1日施行)まで改正され現行有効。単独の「知的財産権規程」という名称の規程は規程集全文検索で確認できなかった。', null, null, 'migration:361'),
  ('reg_5fc4daca90d2_equity_stock_option', 'inst_catalog_5fc4daca90d2', '国立大学法人宇都宮大学におけるライセンス等の対価として取得する株式等取扱要項', 4, 'effective', '規程本文を確認。ライセンス対価を現金で全額支払えないベンチャー等から株式・新株予約権を取得する場合の取扱いを定めた要項。令和2年3月24日制定、令和7年10月16日改正(令和7年11月1日施行)で現行有効。', null, null, 'migration:361'),
  ('reg_5fc4daca90d2_joint_research', 'inst_catalog_5fc4daca90d2', '宇都宮大学における民間機関等との共同研究取扱規程', 4, 'effective', '規程本文を確認。昭和60年制定、令和6年規程第137号(令和6年10月28日施行)まで改正され現行有効。', null, null, 'migration:361'),
  ('reg_5fc4daca90d2_shared_equipment', 'inst_catalog_5fc4daca90d2', '宇都宮大学機器分析センター機器の学外者利用に関する規程', 4, 'effective', '規程本文を確認。教育研究に支障のない範囲で学外者に機器利用を認める規程(令和3年規程第86号、令和3年4月1日施行)。大学発ベンチャー専用の設備共用/インキュベーション施設規程は規程集内で見つからず、最も近い一般的な学外者機器共用規程として登録。', null, null, 'migration:361'),
  ('reg_84b7d5c12a65_recognition', 'inst_catalog_84b7d5c12a65', '岐阜大学における大学発ベンチャーの認定等に関する規程', 4, 'effective', '東海国立大学機構規則集で本文を確認。令和6年5月27日最終改正まで反映された現行規程。同機構規則集内で岐阜大学単独規程として掲載されている。', null, null, 'migration:361'),
  ('reg_84b7d5c12a65_recognition_committee', 'inst_catalog_84b7d5c12a65', '岐阜大学大学発ベンチャー審査委員会細則', 4, 'effective', '認定規程と同じ場所（東海国立大学機構規則集）で本文を確認。審査委員会の構成・運営を定める細則。', null, null, 'migration:361'),
  ('reg_84b7d5c12a65_conflict_of_interest', 'inst_catalog_84b7d5c12a65', '東海国立大学機構利益相反マネジメント規程', 4, 'effective', '岐阜大学は東海国立大学機構（名古屋大学と法人統合）構成大学のため、機構共通規程が岐阜大学にも適用される現行規程として本文を確認した。', null, null, 'migration:361'),
  ('reg_84b7d5c12a65_side_job', 'inst_catalog_84b7d5c12a65', '東海国立大学機構役員及び職員の兼業・兼職に関する規程', 4, 'effective', '機構共通規程。あわせて「東海国立大学機構営利企業役員等兼業審査委員会規程」（act/110010927.html）も同じ分野で確認済み。', null, null, 'migration:361'),
  ('reg_84b7d5c12a65_ip_license', 'inst_catalog_84b7d5c12a65', '東海国立大学機構発明等取扱規程', 4, 'effective', '機構共通規程。関連して著作物取扱規程（act/110010845.html）、商標取扱規程（act/110010846.html）、臨床研究等結果利用許諾等規程（act/110011459.html）も同じ分野（研究戦略部産学官連携課）で確認済み。', null, null, 'migration:361'),
  ('reg_84b7d5c12a65_equity_stock_option', 'inst_catalog_84b7d5c12a65', '東海国立大学機構知的財産権等の運用又は処分に伴う株式等の取扱細則', 4, 'effective', '知財の運用・処分に伴う株式取得等（大学発ベンチャーへの現物出資的な知財ライセンス対価としての株式取得を含む）を規定する細則として本文を確認。国立大学法人としての直接出資（金銭出資）規程ではなく、知財起点の株式取扱いに限定される点に留意。', null, null, 'migration:361'),
  ('reg_84b7d5c12a65_joint_research', 'inst_catalog_84b7d5c12a65', '東海国立大学機構共同研究規程', 4, 'effective', '機構共通規程。岐阜大学独自の共同研究講座・共同研究部門に関する規程（岐阜大学共同研究講座及び共同研究部門規程、act/110010128.html）も別途確認済み。', null, null, 'migration:361'),
  ('reg_2055e944ae82_recognition', 'inst_catalog_2055e944ae82', '国立大学法人京都工芸繊維大学における大学発スタートアップの支援に関する規則', 4, 'effective', '規程集(Reiki-Base)本文を実際に開いて確認。単独の「認定規程」という名称ではなく「支援規則」だが、第2条に認定要件（本学の知財・研究成果に基づく起業、かつ発起人が本学職員等・学生またはその離籍後3年以内の者）、産学公連携推進センター長による決定プロセスを規定しており実質的に認定制度として機能。令和7年2月13日制定、同年3月1日施行。', null, null, 'migration:361'),
  ('reg_2055e944ae82_conflict_of_interest', 'inst_catalog_2055e944ae82', '国立大学法人京都工芸繊維大学役職員利益相反マネジメント規則', 4, 'effective', '規程集本文を実際に開いて確認。利益相反マネジメント委員会の設置、相談窓口運営を規定。平成19年2月15日制定、令和3年9月22日最終改正・同年10月1日施行の現行規則。', null, null, 'migration:361'),
  ('reg_2055e944ae82_side_job', 'inst_catalog_2055e944ae82', '国立大学法人京都工芸繊維大学職員兼業規則', 4, 'effective', '規程集本文を実際に開いて確認。平成16年4月1日制定、令和7年2月13日最終改正・同年3月1日施行（大学発スタートアップ支援規則と同時改正されており、SU関連兼業への対応を含む可能性が高い）。クロスアポイントメント制度は別規則(u042RG00000113、平成29年3月23日制定)として存在することも確認。', null, null, 'migration:361'),
  ('reg_2055e944ae82_ip_license', 'inst_catalog_2055e944ae82', '国立大学法人京都工芸繊維大学発明等規則', 4, 'effective', '規程集本文を実際に開いて確認。第6章「特許権等の実施、維持等」第17条に実施許諾（ライセンス）契約締結に関する規定あり。平成16年9月16日制定、平成30年9月27日最終改正・施行。', null, null, 'migration:361'),
  ('reg_2055e944ae82_equity_stock_option', 'inst_catalog_2055e944ae82', '国立大学法人京都工芸繊維大学におけるライセンス等の対価として取得する株式等取扱規則', 4, 'effective', '規程集本文を実際に開いて確認。大学支援スタートアップがライセンス対価を現金で支払い困難な場合に株式・新株予約権で取得できる制度を規定。産学公連携推進センターが審査、学長が可否決定。令和7年2月13日制定、同年3月1日施行。', null, null, 'migration:361'),
  ('reg_2055e944ae82_joint_research', 'inst_catalog_2055e944ae82', '国立大学法人京都工芸繊維大学共同研究規則', 4, 'effective', '規程集本文を実際に開いて確認。平成17年3月30日制定、令和8年2月12日最終改正・同年4月1日施行予定の最新版を確認。', null, null, 'migration:361'),
  ('reg_2055e944ae82_recognition_committee', 'inst_catalog_2055e944ae82', '京都工芸繊維大学産学公連携推進センター規則（附属のスタートアップ推進室規則を含む）', 4, 'effective', 'recognitionカテゴリの支援規則(u042RG00000061)に同梱される形で確認。単独の「認定委員会」内規は存在せず、審査は産学公連携推進センター運営委員会が担い、決定権はセンター長にある。別途スタートアップ推進室規則(令和7年2月13日制定、u042RG00000201)がセンター内組織として運営委員会設置を規定。', null, null, 'migration:361'),
  ('reg_2055e944ae82_shared_equipment', 'inst_catalog_2055e944ae82', '国立大学法人京都工芸繊維大学が所有する設備等の共用・共同利用における利用料等に関する規則', 4, 'effective', '規程集本文を実際に開いて確認。バイオ/機器分析/マテリアル/クリーンルーム等8ユニットの分析・製造設備の利用料を規定。ただし大学発スタートアップ向けインキュベーション施設利用への言及は本文に無く、学内所属者・学外機関所属者の一般的な設備共用規則。平成30年7月26日制定、令和8年6月11日最終施行版。SU特化の設備共用制度としては未確認。', null, null, 'migration:361'),
  ('reg_e61783be8ca3_recognition', 'inst_catalog_e61783be8ca3', '国立大学法人奈良先端科学技術大学院大学における大学発スタートアップの認定等に関する規程', 4, 'effective', 'PDF本文(第1条〜第4条)を実際に開いて確認。令和6年3月27日制定・規程第5号。研究・イノベーション推進会議の議を経て学長が認定する仕組み。認定委員会単独の内規は別途見当たらず、本規程内に手続が統合されている。認定スタートアップは9社が同ページに掲載されており制度は稼働中。', null, null, 'migration:361'),
  ('reg_e61783be8ca3_conflict_of_interest', 'inst_catalog_e61783be8ca3', '国立大学法人奈良先端科学技術大学院大学利益相反マネジメント規程', 4, 'effective', 'PDF本文(第1条〜第5条)を実際に開いて確認。平成17年3月15日制定・規程第4号。利益相反マネジメント室の設置を規定。別途「利益相反ポリシー」(03190.pdf)も同じ規程集ページに存在し、上位方針として併存している。', null, null, 'migration:361'),
  ('reg_e61783be8ca3_side_job', 'inst_catalog_e61783be8ca3', '国立大学法人奈良先端科学技術大学院大学職員兼業規程', 4, 'effective', 'PDF本文(第1条〜第4条)を実際に開いて確認。平成16年4月1日制定・規程第53号。営利企業の役員兼業を原則不許可としつつ、技術移転事業者・研究成果活用企業(=大学発SU)の役員兼業は許可対象と明記。別途「クロス・アポイントメント制度に関する規程」(平成27年1月30日 規程第2号、08278-1.pdf)も規程集の人事カテゴリに確認できた。', null, null, 'migration:361'),
  ('reg_e61783be8ca3_ip_license', 'inst_catalog_e61783be8ca3', '国立大学法人奈良先端科学技術大学院大学実施許諾等取扱規程', 4, 'effective', 'PDF本文(第1条〜第3条)を実際に開いて確認。平成16年4月1日制定・規程第36号。大学所有の知的財産権(特許権等)の企業等への実施許諾・譲渡を規定。関連して「知的財産ポリシー」(04010.pdf)、「職務発明等取扱規程」(平成16年規程第33号)も同ページで確認済み。', null, null, 'migration:361'),
  ('reg_e61783be8ca3_joint_research', 'inst_catalog_e61783be8ca3', '国立大学法人奈良先端科学技術大学院大学と民間機関等との共同研究取扱規程', 4, 'effective', 'PDF本文(第1条〜第4条)を実際に開いて確認。平成16年4月1日制定・規程第29号。共同研究の定義・受入基準・経費負担を規定。', null, null, 'migration:361'),
  ('reg_e61783be8ca3_shared_equipment', 'inst_catalog_e61783be8ca3', '奈良先端科学技術大学院大学が有する研究設備等の整備・共用の推進に関する規程', 4, 'effective', 'PDF本文(第1条〜第4条)を実際に開いて確認。令和6年3月27日制定・規程第4号。学内外(産官学含む)への研究設備・機器の共用推進を規定。大学発SU専用のインキュベーション施設規程は別途見当たらず、大学発スタートアップ認定規程(03080)側にインキュベーション施設確保が支援内容として明記されている。', null, null, 'migration:361'),
  ('reg_656caf0f3d72_recognition', 'inst_catalog_656caf0f3d72', '国立大学法人北陸先端科学技術大学院大学における大学発ベンチャーの認定及び支援に関する規則', 4, 'effective', '規程集PDFではなくHTML例規集(legalcrud)本文を実際に開いて確認。大学発ベンチャーの定義、認定要件、認定期間(5年、更新は初回5年・以降1年)、審査委員会、称号授与、取消し等を規定。第3条で認定審査を行う「大学発ベンチャー審査委員会」を同一規則内に規定しており、recognition_committeeはこの規則に含まれる。', null, null, 'migration:361'),
  ('reg_656caf0f3d72_recognition_committee', 'inst_catalog_656caf0f3d72', '国立大学法人北陸先端科学技術大学院大学における大学発ベンチャーの認定及び支援に関する規則(第3条 大学発ベンチャー審査委員会)', 4, 'effective', '単独の内規ではなく、recognitionと同一規則の第3条に審査委員会(研究担当理事・未来創造イノベーション推進本部長・産学官連携推進センター長ほかで構成)の規定が同梱されている形。単独ページは別途探していない。', null, null, 'migration:361'),
  ('reg_656caf0f3d72_conflict_of_interest', 'inst_catalog_656caf0f3d72', '国立大学法人北陸先端科学技術大学院大学における利益相反マネジメントに関する規則', 4, 'effective', '実際に本文を開いて確認。役職員の産学連携活動等及び人を対象とする研究における利益相反マネジメントの目的・定義を規定。', null, null, 'migration:361'),
  ('reg_656caf0f3d72_side_job', 'inst_catalog_656caf0f3d72', '国立大学法人北陸先端科学技術大学院大学職員の兼業に関する規則', 4, 'effective', '実際に本文を開いて確認。職員就業規則第31条第2項に基づく兼業取扱いを規定。併せて取扱細則(act/110000060.html)も同分野に存在(未個別確認)。クロス・アポイントメント制度に関する規則(act/110000055.html、人事労務課分野)も別途確認済みリンクあり。', null, null, 'migration:361'),
  ('reg_656caf0f3d72_ip_license', 'inst_catalog_656caf0f3d72', '国立大学法人北陸先端科学技術大学院大学発明規則', 4, 'effective', '実際に本文を開いて確認。職員等の発明の取扱い、発明者の権利保障、知的財産権の帰属を規定する規則で、ライセンス単独規程ではなく発明・知財の基本規則。産学官連携推進センターにおける「知的財産の業務に関する実施細則」(act/110000261.html)も同分野に存在(未個別確認、実施レベルの細則)。', null, null, 'migration:361'),
  ('reg_656caf0f3d72_equity_stock_option', 'inst_catalog_656caf0f3d72', '国立大学法人北陸先端科学技術大学院大学における新株予約権の取得に関する規則', 4, 'effective', '実際に本文を開いて確認。科学技術・イノベーション創出の活性化に関する法律に基づき、知的財産等のライセンス等の対価として新株予約権を取得する規則。姉妹規則として「新株予約権の管理に関する規則」(act/110000430.html)も同分野に存在(未個別確認、取得後の管理規定と推定)。', null, null, 'migration:361'),
  ('reg_656caf0f3d72_joint_research', 'inst_catalog_656caf0f3d72', '国立大学法人北陸先端科学技術大学院大学共同研究取扱規則', 4, 'effective', '実際に本文を開いて確認。頻繁に改正されており最新の産学連携実務を反映していると見られる。受託研究取扱規則(act/110000158.html)、技術サービス取扱規則(act/110000160.html)も同分野に別途存在(未個別確認)。', null, null, 'migration:361'),
  ('reg_656caf0f3d72_shared_equipment', 'inst_catalog_656caf0f3d72', '北陸先端科学技術大学院大学JAISTイノベーションプラザ利用規則', 4, 'effective', '実際に本文を開いて確認。北陸地域(富山・石川・福井)の企業等が利用対象のインキュベーション施設(JAISTイノベーションプラザ)の利用規則。同種としてベンチャー・ビジネス・ラボラトリー利用規則(act/110000258.html)も同分野に存在(未個別確認)。厳密には大学発SU限定ではなく地域企業一般向けの施設利用規則。', null, null, 'migration:361'),
  ('reg_1abfa9e22bbc_recognition', 'inst_catalog_1abfa9e22bbc', '東京都公立大学法人大学等発ベンチャー支援に関する規程', 4, 'effective', '公式規程集（g-reiki）で本文を確認済み。平成24年12月28日制定・法人規程第2号、令和8年4月1日施行版。東京都立大学・東京都立産業技術大学院大学・東京都立産業技術高等専門学校の3法人が対象。称号使用、施設利用、知財ライセンス対価の新株予約権化等の支援を規定、支援期間は5年以内でベンチャー支援審査会が審議。', null, null, 'migration:361'),
  ('reg_f77a046888fb_recognition', 'inst_catalog_f77a046888fb', '京都府公立大学法人における大学発ベンチャー企業の認定等に関する規程', 4, 'effective', '京都府公立大学法人規程第49号。令和7年1月31日制定、令和7年4月1日施行。京都府立医科大学と京都府立大学を設置する京都府公立大学法人共通の規程で、全14条をPDF原文で確認済み。認定手続、称号授与、便宜措置（施設貸与・商業登記許可・研究設備利用許可）、認定取消まで規定。', null, null, 'migration:361'),
  ('reg_f77a046888fb_recognition_committee', 'inst_catalog_f77a046888fb', '京都府立医科大学発ベンチャー審査委員会（大学発ベンチャー認定等に関する規程第3条に規定）', 4, 'effective', '認定規程第3条に基づき京都府立医科大学に設置される審査委員会。委員会の詳細規定は「別に定める」とされ内規本体は未確認（規程集は学内限定で非公開）。設置根拠条文のみ本PDF内で確認済み。', null, null, 'migration:361'),
  ('reg_f77a046888fb_support_rules', 'inst_catalog_f77a046888fb', '大学発ベンチャー企業の認定等に関する規程 第7条（便宜措置）', 4, 'effective', '独立の支援細則は見当たらないが、認定規程第7条が事務室・研究室の貸与、商業登記許可、研究設備利用許可などの支援措置を規定しており、これがSU支援ルールに相当する。単独の支援細則文書は確認できていない。', null, null, 'migration:361'),
  ('reg_f77a046888fb_conflict_of_interest', 'inst_catalog_f77a046888fb', '京都府公立大学法人の利益相反の管理に関する規程', 4, 'effective', '京都府公立大学法人規程第32号。平成21年8月1日制定。京都府立医科大学・京都府立大学共通規程で、利益相反委員会の設置、個人・組織としての利益相反管理を規定。PDF原文（1ページ目）で確認済み。別途「利益相反ポリシー」「臨床研究等に係る利益相反の管理に関する取扱規程」も同ページに公開されている。', null, null, 'migration:361'),
  ('reg_f77a046888fb_side_job', 'inst_catalog_f77a046888fb', '京都府公立大学法人教職員兼業規程', 4, 'effective', '京都府公立大学法人規程第10号。平成20年4月1日制定、平成25年改正あり。技術移転兼業・研究成果活用兼業・監査役兼業など大学発ベンチャー関連の役員兼業許可規定を含む全17条をPDF原文で確認済み。クロスアポイントメント制度への言及は本規程内には見当たらない。', null, null, 'migration:361'),
  ('reg_f77a046888fb_ip_license', 'inst_catalog_f77a046888fb', '教職員等の職務発明等に関する規程', 4, 'effective', '京都府公立大学法人規程第31号。平成21年4月1日制定。職務発明の認定、権利承継の手続を規定。PDF原文（1ページ目）で確認済み。別途「京都府公立大学法人知的財産ポリシー」（PDF: /corporation/files/23765.pdf）も同ページに公開されているが未読み込み。実施許諾（ライセンス）の個別条項までは今回未確認。', null, null, 'migration:361'),
  ('reg_f77a046888fb_joint_research', 'inst_catalog_f77a046888fb', '京都府立医科大学共同研究取扱規程', 4, 'effective', '京都府立医科大学規程第91号。平成20年4月1日制定、平成25年一部改正。民間機関等との共同研究の受入れ、申請、承認手続を規定。PDF原文（1ページ目）で確認済み。', null, null, 'migration:361'),
  ('reg_46957a06d459_recognition', 'inst_catalog_46957a06d459', '学校法人自治医科大学における大学発ベンチャー認定に関する規程', 4, 'effective', '産学官連携ページ「大学発ベンチャー」内の規程等一覧からPDF本体を確認。同ページには認定企業11社（DeepEyeVision、IchiGoo、ナーステックラボ等）の実名リストも掲載されており、制度が実際に運用中と確認できる。改正年月日はPDFファイル名からは不明（本文未確認、ファイル一覧上の表題のみ確認）。', null, null, 'migration:361'),
  ('reg_46957a06d459_equity_stock_option', 'inst_catalog_46957a06d459', '自治医科大学発ベンチャーから取得する株式等取扱規程', 4, 'effective', '同じ「大学発ベンチャー」ページの規程等一覧に掲載。大学発ベンチャーから取得する株式等の取扱いを定めた規程で、認定規程とセットで公開されている。改正年月日は未確認。', null, null, 'migration:361'),
  ('reg_46957a06d459_shared_equipment', 'inst_catalog_46957a06d459', '大学発ベンチャーへの事務室等の貸与について', 4, 'effective', '認定ベンチャーへの学内施設（事務室等）貸与・研究設備利用に関する取扱いを定めた文書。「大学発ベンチャー」ページ本文でも「学内施設の貸与や研究設備の利用」支援を行っている旨明記。ページ本文の未読部分に基づく規程性質の確認は簡易的。', null, null, 'migration:361'),
  ('reg_46957a06d459_conflict_of_interest', 'inst_catalog_46957a06d459', '学校法人自治医科大学利益相反マネジメント・ポリシー', 4, 'effective', '産学官連携ページ「利益相反」内で本文閲覧済み。平成21年4月1日制定と本文に明記。同ページには利益相反委員会内規（Bylaw.pdf）、人を対象とする医学系研究に係る利益相反ポリシー、臨床研究等に係る利益相反手順書も併せて公開されている。', null, null, 'migration:361'),
  ('reg_46957a06d459_joint_research', 'inst_catalog_46957a06d459', '共同研究取扱規程', 4, 'effective', '産学官連携ページ「共同研究」内の規程等一覧からPDFファイル名・表題を確認（表題「共同研究取扱規程(123KB)」）。本文は未確認、令和7年度分の共同研究実績PDFまで継続更新されており現行運用中と判断。', null, null, 'migration:361'),
  ('reg_46957a06d459_ip_license', 'inst_catalog_46957a06d459', '自治医科大学発明等取扱規程', 4, 'effective', '産学官連携ページ「知的財産＞発明」内で本文閲覧済み。「教職員の研究成果により生み出された職務発明等の権利を保障し…特許権等の知的財産権を大学が管理、運用する」規程として運用中。令和7年度分の主要特許一覧・知的財産管理状況一覧も同ページで更新されており現行運用が確認できる。', null, null, 'migration:361'),
  ('reg_9e581f664d73_conflict_of_interest', 'inst_catalog_9e581f664d73', '川崎医科大学利益相反マネジメント規程', 4, 'effective', '2023年9月1日改正の規程本文PDFを確認。関連する「利益相反マネジメントに係る基準」(2024年8月1日改定)も同ページに公開されている。一般公開ページから直接PDFへリンクされており実在を確認済み。', null, null, 'migration:361'),
  ('reg_9e581f664d73_recognition', 'inst_catalog_9e581f664d73', '大学発ベンチャー（起業）支援制度', 4, 'effective', '産学連携知的財産管理室のページで大学発ベンチャー起業の手続きを紹介し、大学発ベンチャー支援申請書・兼業許可申請書・事業報告書の様式を公開している。ただし「認定規程」という名称の独立した規程本文PDFは公開ページ上に見当たらず、申請ベースの支援制度説明にとどまる。認定委員会の記載も確認できなかった。', null, null, 'migration:361'),
  ('reg_9e581f664d73_ip_license', 'inst_catalog_9e581f664d73', '川崎医科大学　知的財産ポリシー／産学官連携ポリシー', 4, 'effective', '令和2年6月8日施行の知的財産ポリシー・産学官連携ポリシーの全文をページ上で確認。個別の「知的財産権規程」という名称の単独PDFは見当たらず、ポリシー文書が実質的な正本として公開されている。', null, null, 'migration:361'),
  ('reg_9e581f664d73_joint_research', 'inst_catalog_9e581f664d73', '川崎医科大学産学官連携ポリシー（共同研究・受託研究ページ経由のPDF）', 4, 'effective', '共同研究・受託研究ページに産学官連携ポリシーPDFへのリンクと、共同研究申込書・受託研究申込書の様式が掲載されている。共同研究等取扱規則という単独名称の規則は確認できず、上記ポリシーが該当。', null, null, 'migration:361'),
  ('reg_7cd85e860bcd_conflict_of_interest', 'inst_catalog_7cd85e860bcd', '研究開発型ベンチャーの役員兼業に関する利益相反マネジメント規程', 4, 'effective', '早稲田大学研究倫理オフィス「利益相反マネジメント」ページ(https://www.waseda.jp/inst/ore/conflict、HTTP200で閲覧確認済み)に規程名とPDFリンク(https://www.waseda.jp/inst/ore/assets/uploads/2026/07/80a3969b283373e2ef66b1d5fd656544.pdf)が掲載されているのを確認。同ページには「産学連携活動等に伴う研究開発型ベンチャー兼業における利益相反に関する基本方針」も併記。PDF本体は同ドメインのCloudflareボット対策により直接fetchが403で拒否されたため本文までは未確認、規程名・所在のみ確認済み。一般的な公的研究費/外部資金COI規程(Regulations_COI.pdf、2009年〜)とは別に、大学発ベンチャーの役員兼業に特化した規程として独立に存在している。', null, null, 'migration:361'),
  ('reg_7cd85e860bcd_ip_license', 'inst_catalog_7cd85e860bcd', '早稲田大学職務発明規程', 4, 'effective', '研究推進部「早稲田大学の産官学連携について」ページ(https://www.waseda.jp/inst/research/tlo/industrycollaboration、HTTP200で閲覧確認済み、#anc_27規約・書式集セクション)に規程名とPDFリンク(https://www.waseda.jp/inst/research/assets/uploads/2026/07/20250401_inventorrule.pdf、ファイル名から施行日2025-04-01と推定)を確認。同ページには関連文書として「知的財産に関する基本理念」「企業との共同研究等において生じる知的財産権の取扱い等に関する基本方針」(施行2024-07-01)も掲載。PDF本体はCloudflareボット対策で直接fetch不可(403)、本文未確認。', null, null, 'migration:361'),
  ('reg_7cd85e860bcd_joint_research', 'inst_catalog_7cd85e860bcd', '学外機関等との学術研究提携等に関する規則', 4, 'effective', '同じく「早稲田大学の産官学連携について」ページ(https://www.waseda.jp/inst/research/tlo/industrycollaboration)にPDFリンク(http://www.waseda.jp/top/assets/uploads/2015/05/gakujyutuskikan_gkisaoku.pdf)を確認。ただし他大学の「共同研究等取扱規則」に相当する名称の全学規程として確認できたのはこれのみで、内容は学外機関との学術研究提携全般を対象とする規則であり、共同研究契約に特化した規則かは本文未確認(PDFはCloudflareボット対策で直接fetch不可)。理工学術院総合研究所には別途「受託・共同研究等の契約に関する指針」という部局レベルの文書も存在(https://www.waseda.jp/fsci/wise/assets/uploads/2020/05/160714keiyaku_shishin.pdf)し、全学規程とは別物である点に注意。', null, null, 'migration:361'),
  ('reg_2e634684f6dc_conflict_of_interest', 'inst_catalog_2e634684f6dc', '慶應義塾利益相反マネジメント内規', 4, 'effective', '上記ポリシーに付随する内規として同ページに掲載されているPDFリンクを確認した。／関連文書: 慶應義塾利益相反マネジメント・ポリシー も版履歴として確認済み。', null, null, 'migration:361'),
  ('reg_2e634684f6dc_side_job', 'inst_catalog_2e634684f6dc', '研究成果活用企業の役員等の兼業手続きに関するガイドライン', 4, 'effective', '産学官連携カテゴリに分類されたガイドラインで、大学発ベンチャー等(研究成果活用企業)の役員兼業手続きを定めるものと確認した。一般教職員向けの包括的な兼業規程とは別立てで、対象は研究成果活用企業役員兼業に限定されている点に留意。', null, null, 'migration:361'),
  ('reg_2e634684f6dc_ip_license', 'inst_catalog_2e634684f6dc', '慶應義塾発明取扱規程', 4, 'effective', '知的財産の帰属・承継・実施許諾の基礎となる規程。2025/1/1施行版のPDFリンクを確認した。／関連文書: 慶應義塾スタートアップ向け技術移転ガイドライン、慶應義塾知的財産ポリシー も版履歴として確認済み。', null, null, 'migration:361'),
  ('reg_33f367188cf9_ip_license', 'inst_catalog_33f367188cf9', '立命館大学発明規程', 4, 'effective', '同じ知的財産ページからPDF全文を取得し200 OKで存在確認済み。本文冒頭に1992年3月27日 規程第253号と明記（職務発明の帰属・発明委員会等を規定）。公開されている全文が現行版として案内されている。／関連文書: 立命館大学知的財産ポリシー も版履歴として確認済み。', null, null, 'migration:361'),
  ('reg_e437d589dc87_recognition', 'inst_catalog_e437d589dc87', '大学認定スタートアップ制度', 4, 'effective', '2002年開始の制度で、産学連携機構(UURA)サイトに紹介ページがあり、2026年8月時点で21社を認定と明記。ただし認定基準・申請要件を定めた規程本文のPDFは学外に公開されておらず、教員向け申請はポータル内フォーム、学生向けはBox経由の限定公開リンクのみ確認できた。規程集自体が一般公開されていない機関のため、支援制度紹介ページを一次情報として採用。', null, null, 'migration:361'),
  ('reg_e437d589dc87_support_rules', 'inst_catalog_e437d589dc87', '大学発スタートアップ支援制度（起業ハンドブック・PoC支援・伴走支援等）', 4, 'effective', '産学連携機構の同一ページに、起業ハンドブック配布、学内助成金(PoC支援)、学外助成金(GTIEギャップファンド、1stRound)、伴走支援を含む支援メニューが列挙されている。個別の細則PDFへのリンクは確認できず、紹介ページの記載内容のみで裏取り。', null, null, 'migration:361'),
  ('reg_e437d589dc87_shared_equipment', 'inst_catalog_e437d589dc87', 'スタートアップ向け施設支援（インキュベーションルーム／産学試作開発室／ベンチャースタジオ）', 4, 'effective', '同じ支援制度紹介ページに、大学認定スタートアップ等が使えるインキュベーションルーム、産学試作開発室、学生向けコワーキングスペース「ベンチャースタジオ」、quantum cross point(qcp)との連携が明記されている。単独の規程文書は見つからず、紹介ページの記載で確認。', null, null, 'migration:361'),
  ('reg_c8343bcae1a5_ip_license', 'inst_catalog_c8343bcae1a5', '名城大学知的財産ポリシー', 4, 'effective', 'PDF原文を実際に取得して確認済み。平成16年6月11日制定、令和7年4月1日改正施行の現行版。「(2)スタートアップの起業に必要な権利の確立」「(2)スタートアップへの知的財産のライセンス」の章があり、大学発スタートアップへの優先的な実施許諾・新株予約権/株式による対価受領の選択肢まで明記されている。産官学連携・研究支援サイト(sangaku.meijo-u.ac.jp)の知的財産ページから正規に公開されているPDFで、実在URLを直接読み込んで内容を検証した。', null, null, 'migration:361'),
  ('reg_c8343bcae1a5_conflict_of_interest', 'inst_catalog_c8343bcae1a5', '名城大学利益相反マネジメントポリシー／名城大学利益相反マネジメント要項', 4, 'effective', '産官学連携・研究支援サイトの「利益相反」ページ本文で規程名・運用（自己申告書提出→利益相反マネジメント委員会審査）を確認したが、規程原文PDF自体は学内限定(campusonly)に格納されており、一般公開のダイレクトリンクは見つからなかった。名城大学は規程集（reiki系サイト）を一般公開していない模様で、他の一次規程URLも同様に未発見。', null, null, 'migration:361'),
  ('reg_c8343bcae1a5_joint_research', 'inst_catalog_c8343bcae1a5', '共同研究契約等の秘密情報管理要項', 4, 'effective', '受託研究・共同研究の申請ページ(sangaku.meijo-u.ac.jp/collaboration/entrust/)からPDFリンクを実際に確認。共同研究等取扱規則そのものの単独公開ページは見つからず、代わりに同ページで運用されている秘密情報管理要項（2024年4月版）と学生参加に関する方針(student-participation-policy_202404.pdf)が公開一次資料として確認できた唯一のもの。', null, null, 'migration:361'),
  ('reg_bbc28fa08564_recognition', 'inst_catalog_bbc28fa08564', '国立研究開発法人国立環境研究所ベンチャー支援規程', 4, 'effective', 'PDF原文を実際に取得し全文確認済み。令和4年11月1日制定・施行(令4規程第1号)。国環研ベンチャーの認定要件、ベンチャー審査委員会(第3条)、支援内容(場所無償貸与、知財の独占的利用許諾、実施料減免等)、認定取消し等を規定。2024年9月時点の認定企業(株式会社野生動物医科学ラボラトリー)も産学連携サイトに掲載されている。国立環境研究所は大学ではなく国立研究開発法人だが、大学発ベンチャー相当の自法人発ベンチャー認定制度を持つ。', null, null, 'migration:361'),
  ('reg_bbc28fa08564_recognition_committee', 'inst_catalog_bbc28fa08564', '国立研究開発法人国立環境研究所ベンチャー審査委員会', 4, 'effective', 'ベンチャー支援規程第3条に規定される認定審査委員会。単独の規程PDFは確認できておらず、支援規程内の条文として存在を確認した(委員会の運営等の詳細は「別に定める」とあり非公開の可能性)。', null, null, 'migration:361'),
  ('reg_bbc28fa08564_conflict_of_interest', 'inst_catalog_bbc28fa08564', '国立研究開発法人国立環境研究所利益相反マネジメント実施規程', 4, 'effective', 'PDF原文を実際に取得し1ページ目を確認済み。平成27年1月16日制定(平26規程第1号)、直近改正は令和8年3月30日。利益相反マネジメント委員会、定期自己申告マネジメント、事象発生時マネジメント等の章立てを持つ現行規程。', null, null, 'migration:361'),
  ('reg_bbc28fa08564_side_job', 'inst_catalog_bbc28fa08564', '国立研究開発法人国立環境研究所兼業等規程', 4, 'effective', 'PDF原文を実際に取得し1ページ目を確認済み。平成18年4月1日制定(平18規程第13号)、直近改正は令和元年5月17日。職員就業規則・任期付職員就業規則に基づく兼業・自営・副業の許可基準を規定。クロスアポイントメント制度への直接言及は1ページ目時点では未確認(全文精査は未実施)。', null, null, 'migration:361'),
  ('reg_bbc28fa08564_ip_license', 'inst_catalog_bbc28fa08564', '国立研究開発法人国立環境研究所知的財産取扱規程', 4, 'effective', 'PDF原文を実際に取得し1ページ目を確認済み。平成13年4月1日制定(平13規程第34号)、直近改正は令和8年3月30日。役職員が創出した知的財産の帰属・管理・活用を規定する現行規程。実施許諾(ライセンス)条項の有無は1ページ目時点では未確認(全文精査は未実施)。産学連携サイトでは「原始使用者帰属」を定める規程として案内されている。', null, null, 'migration:361'),
  ('reg_bbc28fa08564_joint_research', 'inst_catalog_bbc28fa08564', '国立研究開発法人国立環境研究所共同研究実施規程', 4, 'effective', 'PDF原文を実際に取得し1ページ目を確認済み。平成13年5月11日制定(平13規程第42号)、直近改正は令和6年1月26日。研究所以外の者との共同研究の実施手続き・知的財産の定義等を規定する現行規程。', null, null, 'migration:361'),
  ('reg_bbc28fa08564_shared_equipment', 'inst_catalog_bbc28fa08564', '国立研究開発法人国立環境研究所固定資産等管理事務取扱細則(令2細則第1号)第28条・第29条', 4, 'effective', '単独規程としては未確認。ベンチャー支援規程第6条内で、国環研ベンチャーへの事務室・研究室・研究設備の無償貸与や登記住所使用の根拠として引用されている条文の存在のみ確認した。細則そのもののURLは未特定。', null, null, 'migration:361'),
  ('reg_qst_conflict_of_interest', 'inst_qst', '利益相反マネジメント規程', 4, 'effective', '公式サイトの規程専用ページでPDF掲載を確認済み。最新版は2025年4月1日付。', null, null, 'migration:361'),
  ('reg_qst_recognition', 'inst_qst', 'QSTベンチャー支援制度', 4, 'effective', '公式サイトの制度紹介ページを確認済み。ベンチャー認定・支援の制度自体は運用中だが、規程本文PDFの単独URLは今回特定できず、制度紹介ページを一次情報として採用。', null, null, 'migration:361')
