-- 361_su_regulations_bulk_research_2026-09-01.sql
-- 2026-09-01 ultracode並列ワークフローで、SU関連規程が未登録だった40機関ぶんを
-- 公式サイト・規程集（学内規則データベース含む）から desk research し、実在確認済みURLのみ登録する。
-- 対象外（今回の公開情報検索では未確認、次回ヒアリング/再検索対象）:
-- 東京電機大学 (inst_catalog_35b5c217ec7b)
-- 産業技術総合研究所 (inst_catalog_dd388f7debe3)
-- 国立がん研究センター (inst_catalog_18402bd4d9e6)
-- 森林研究・整備機構 森林総合研究所 (inst_catalog_f47662863af3)

on conflict (regulation_id) do update set
  title = excluded.title,
  stage = excluded.stage,
  lifecycle_state = excluded.lifecycle_state,
  current_state_note = excluded.current_state_note,
  updated_by = excluded.updated_by,
  updated_at = now();

on conflict (institution_id, regulation_type_id) do update set
  regulation_id = excluded.regulation_id,
  state = excluded.state,
  confirmed_at = excluded.confirmed_at,
  updated_by = excluded.updated_by,
  updated_at = now();

on conflict (version_id) do update set
  label = excluded.label,
  version_state = excluded.version_state,
  external_url = excluded.external_url,
  version_date = excluded.version_date,
  is_current = excluded.is_current,
  created_by = excluded.created_by,
  updated_at = now();
